const communityMyanmar={"title":"အသိုင်းအဝိုင်းအတွက် မေးခွန်းများနှင့် မျှဝေမှု","intro":"သင်ယုံကြည်ရသူတစ်ဦးအတွက် မေးခွန်းတစ်ခု သို့မဟုတ် အသုံးဝင်သော အတွေ့အကြုံတစ်ခုကို ပြင်ဆင်ပါ။ စိစစ်ပြီးသော အသိုင်းအဝိုင်းအချက်အလက်များ ရရှိလာသည့်အခါ ဤနေရာတွင် ဖတ်ရှုနိုင်ပါသည်။","status":"Lift သည် အသိုင်းအဝိုင်းထံမှ ပေးပို့ချက်များကို လက်မခံသေးပါ။ ဤနေရာတွင် သင်ရေးထားသမျှကို Lift ထံ ပို့ခြင်း သို့မဟုတ် ထုတ်ဝေခြင်း မရှိပါ။","kind":"မည်သည့်အရာကို ပြင်ဆင်လိုပါသလဲ။","question":"မေးခွန်းတစ်ခု","experience":"မျှဝေလိုသော အတွေ့အကြုံတစ်ခု","topic":"အကြောင်းအရာတစ်ခုကို ရွေးပါ","daily":"နေ့စဉ်ဘဝ","family":"မိသားစုနှင့် သင်ယူမှု","work":"အလုပ်နှင့် ဝင်ငွေ","documents":"စာရွက်စာတမ်းများနှင့် ရက်စွဲများ","health":"ကျန်းမာရေးနှင့် အကူအညီ","prompt":"သင့်မေးခွန်း သို့မဟုတ် အတွေ့အကြုံ","placeholder":"ဥပမာ၊ အိမ်ငှားစပေါ်ငွေ မပေးမီ မည်သည့်အချက်များကို မေးသင့်ပါသလဲ။","safety":"အမည်များ၊ ဖုန်းနံပါတ်များ၊ စာရွက်စာတမ်းနံပါတ်များ၊ လိပ်စာအတိအကျနှင့် အခြားသူတစ်ဦးကို ဖော်ထုတ်နိုင်သော အသေးစိတ်အချက်များကို မထည့်ပါနှင့်။ အကျိုးဆောင်များ သို့မဟုတ် အလုပ်ရှင်များ၏ အမည်များကို မဖော်ပြပါနှင့်။","privacy":"သင့်မူကြမ်းသည် ယခုဖွင့်ထားသော စာမျက်နှာထဲတွင်သာ ရှိနေပါသည်။ အစီအစဉ်သိမ်းဆည်းမှု ဖွင့်ထားလျှင်လည်း စာမျက်နှာကို ပြန်လည်တင်ခြင်း သို့မဟုတ် ရှင်းလင်းခြင်းဖြင့် မူကြမ်းကို ဖယ်ရှားပါသည်။ သင်ကူးယူ၊ ဒေါင်းလုဒ်လုပ် သို့မဟုတ် မျှဝေထားသော စာသားသည် Lift ပြင်ပတွင် ကျန်ရှိပါသည်။","preview":"ကျွန်ုပ်၏မူကြမ်းကို ပြန်ကြည့်ပါ","previewTitle":"သင့်မူကြမ်း — မစိစစ်ရသေးပါ","draftNote":"ဤသည်မှာ ကိုယ်ပိုင်မေးခွန်း သို့မဟုတ် အတွေ့အကြုံဖြစ်ပြီး အတည်ပြုထားသော အချက်အလက် မဟုတ်ပါ။ Lift က စိစစ်ခြင်း သို့မဟုတ် ထုတ်ဝေခြင်း မပြုရသေးပါ။","share":"ကျွန်ုပ်၏မူကြမ်းကို မျှဝေပါ","copy":"ကျွန်ုပ်၏မူကြမ်းကို ကူးယူပါ","download":"ကျွန်ုပ်၏မူကြမ်းကို ဒေါင်းလုဒ်လုပ်ပါ","clear":"ကျွန်ုပ်၏မူကြမ်းကို ရှင်းလင်းပါ","edit":"ကျွန်ုပ်၏မူကြမ်းကို ပြင်ဆင်ပါ","empty":"မေးခွန်း သို့မဟုတ် အတွေ့အကြုံတစ်ခုကို ဦးစွာ ရေးပါ။","tooLong":"မူကြမ်းကို စာလုံးရေ 1,200 အတွင်း ရေးပါ။","shareHelp":"အက်ပ်နှင့် လက်ခံမည့်သူကို သင်ရွေးချယ်ပါသည်။ မျှဝေခြင်းသည် မူကြမ်းကို Lift ထံ ပေးပို့ခြင်း မဟုတ်သကဲ့သို့ စိစစ်ပြီးသော အသိုင်းအဝိုင်းပို့စ်အဖြစ် ပြောင်းလဲခြင်းလည်း မဟုတ်ပါ။","fallback":"မျှဝေ၍ မရပါ။ အစားထိုးအနေဖြင့် သင့်မူကြမ်းကို ကူးယူနိုင်ပါသည် သို့မဟုတ် ဒေါင်းလုဒ်လုပ်နိုင်ပါသည်။","copied":"မူကြမ်းကို ကူးယူပြီးပါပြီ။ မည်သည့်နေရာတွင် ထည့်မည်ကို သင်ရွေးချယ်ပါသည်။","copyFailed":"ကူးယူ၍ မရပါ။ အစားထိုးအနေဖြင့် သင့်မူကြမ်းကို ဒေါင်းလုဒ်လုပ်နိုင်ပါသည်။","cleared":"သင့်မူကြမ်းကို ဤစာမျက်နှာမှ ရှင်းလင်းပြီးပါပြီ။","board":"စိစစ်ပြီးသော အသိုင်းအဝိုင်းအချက်အလက်များ","noPosts":"စိစစ်ပြီးသော အသိုင်းအဝိုင်းပို့စ်များ မရှိသေးပါ။ ကိုယ်ပိုင်မူကြမ်းများကို အလိုအလျောက် ထည့်သွင်းခြင်း လုံးဝမရှိပါ။","reviewExplain":"မထုတ်ဝေမီ လူတစ်ဦးက အသုံးအနှုန်းများကို စိစစ်ခြင်း၊ မည်သူဖြစ်ကြောင်း ဖော်ထုတ်နိုင်သော အချက်များကို ဖယ်ရှားခြင်းနှင့် ရင်းမြစ်များကို စစ်ဆေးခြင်း ပြုလုပ်ရပါမည်။ ဥပဒေနှင့် ကျန်းမာရေးအချက်အလက်များအတွက် သက်ဆိုင်ရာအရည်အချင်းရှိသော စိစစ်သူလည်း လိုအပ်ပါသည်။ အတွေ့အကြုံများကို အတွေ့အကြုံဖြစ်ကြောင်း တပ်ဖော်ပြရပါမည်။","source":"ရင်းမြစ်ကို ဖတ်ပါ","reviewed":"စိစစ်ခဲ့သည့်ရက်","due":"ပြန်လည်စိစစ်ရမည့်ရက်","stale":"ပြန်လည်စိစစ်ရမည့်ရက် ကျော်လွန်နေပါသည်။ ဤပို့စ်ကို မမှီခိုမီ မူရင်းရင်းမြစ်ကို စစ်ဆေးပါ။","experienceLabel":"ကိုယ်ပိုင်အတွေ့အကြုံ — သင့်အခြေအနေနှင့် ကိုက်ညီချင်မှ ကိုက်ညီပါမည်","answerLabel":"ရင်းမြစ်အထောက်အထားရှိသော အချက်အလက်","notEmergency":"ဤစာမျက်နှာကို စောင့်ကြည့်နေသူ မရှိသဖြင့် အရေးပေါ်အကူအညီ မပေးနိုင်ပါ။ အကူအညီလိုအပ်သည့်အခါ အကူအညီပေးသော ဝန်ဆောင်မှုကို တိုက်ရိုက် အသုံးပြုပါ။","help":"အကူအညီဆိုင်ရာ အချက်အလက်ကို ရှာပါ","back":"ကျွန်ုပ်၏မူကြမ်းသို့ ပြန်သွားပါ"};
Object.assign(window.LiftMyanmar,{"Community questions and sharing":"အသိုင်းအဝိုင်းအတွက် မေးခွန်းများနှင့် မျှဝေမှု","Prepare a question or a useful experience for someone you trust. Read reviewed community information here when it becomes available.":"သင်ယုံကြည်ရသူတစ်ဦးအတွက် မေးခွန်းတစ်ခု သို့မဟုတ် အသုံးဝင်သော အတွေ့အကြုံတစ်ခုကို ပြင်ဆင်ပါ။ စိစစ်ပြီးသော အသိုင်းအဝိုင်းအချက်အလက်များ ရရှိလာသည့်အခါ ဤနေရာတွင် ဖတ်ရှုနိုင်ပါသည်။","Lift is not receiving community submissions yet. Nothing you write here is sent to Lift or published.":"Lift သည် အသိုင်းအဝိုင်းထံမှ ပေးပို့ချက်များကို လက်မခံသေးပါ။ ဤနေရာတွင် သင်ရေးထားသမျှကို Lift ထံ ပို့ခြင်း သို့မဟုတ် ထုတ်ဝေခြင်း မရှိပါ။","What would you like to prepare?":"မည်သည့်အရာကို ပြင်ဆင်လိုပါသလဲ။","A question":"မေးခွန်းတစ်ခု","An experience to share":"မျှဝေလိုသော အတွေ့အကြုံတစ်ခု","Choose a topic":"အကြောင်းအရာတစ်ခုကို ရွေးပါ","Everyday life":"နေ့စဉ်ဘဝ","Family and learning":"မိသားစုနှင့် သင်ယူမှု","Work and earnings":"အလုပ်နှင့် ဝင်ငွေ","Documents and dates":"စာရွက်စာတမ်းများနှင့် ရက်စွဲများ","Health and support":"ကျန်းမာရေးနှင့် အကူအညီ","Your question or experience":"သင့်မေးခွန်း သို့မဟုတ် အတွေ့အကြုံ","For example: What should I ask before paying a housing deposit?":"ဥပမာ၊ အိမ်ငှားစပေါ်ငွေ မပေးမီ မည်သည့်အချက်များကို မေးသင့်ပါသလဲ။","Leave out names, phone numbers, document numbers, exact addresses and details identifying another person. Please do not name agents or employers.":"အမည်များ၊ ဖုန်းနံပါတ်များ၊ စာရွက်စာတမ်းနံပါတ်များ၊ လိပ်စာအတိအကျနှင့် အခြားသူတစ်ဦးကို ဖော်ထုတ်နိုင်သော အသေးစိတ်အချက်များကို မထည့်ပါနှင့်။ အကျိုးဆောင်များ သို့မဟုတ် အလုပ်ရှင်များ၏ အမည်များကို မဖော်ပြပါနှင့်။","Your draft stays only in this open page. Reloading or clearing removes it, even if plan saving is on. Text you copy, download or share remains outside Lift.":"သင့်မူကြမ်းသည် ယခုဖွင့်ထားသော စာမျက်နှာထဲတွင်သာ ရှိနေပါသည်။ အစီအစဉ်သိမ်းဆည်းမှု ဖွင့်ထားလျှင်လည်း စာမျက်နှာကို ပြန်လည်တင်ခြင်း သို့မဟုတ် ရှင်းလင်းခြင်းဖြင့် မူကြမ်းကို ဖယ်ရှားပါသည်။ သင်ကူးယူ၊ ဒေါင်းလုဒ်လုပ် သို့မဟုတ် မျှဝေထားသော စာသားသည် Lift ပြင်ပတွင် ကျန်ရှိပါသည်။","Review my draft":"ကျွန်ုပ်၏မူကြမ်းကို ပြန်ကြည့်ပါ","Your draft — not reviewed":"သင့်မူကြမ်း — မစိစစ်ရသေးပါ","This is a personal question or experience, not verified information. It has not been reviewed or published by Lift.":"ဤသည်မှာ ကိုယ်ပိုင်မေးခွန်း သို့မဟုတ် အတွေ့အကြုံဖြစ်ပြီး အတည်ပြုထားသော အချက်အလက် မဟုတ်ပါ။ Lift က စိစစ်ခြင်း သို့မဟုတ် ထုတ်ဝေခြင်း မပြုရသေးပါ။","Share my draft":"ကျွန်ုပ်၏မူကြမ်းကို မျှဝေပါ","Copy my draft":"ကျွန်ုပ်၏မူကြမ်းကို ကူးယူပါ","Download my draft":"ကျွန်ုပ်၏မူကြမ်းကို ဒေါင်းလုဒ်လုပ်ပါ","Clear my draft":"ကျွန်ုပ်၏မူကြမ်းကို ရှင်းလင်းပါ","Edit my draft":"ကျွန်ုပ်၏မူကြမ်းကို ပြင်ဆင်ပါ","Write a question or experience first.":"မေးခွန်း သို့မဟုတ် အတွေ့အကြုံတစ်ခုကို ဦးစွာ ရေးပါ။","Please keep your draft within 1,200 characters.":"မူကြမ်းကို စာလုံးရေ 1,200 အတွင်း ရေးပါ။","You choose the app and recipient. Sharing does not submit a draft to Lift and does not make it a reviewed community post.":"အက်ပ်နှင့် လက်ခံမည့်သူကို သင်ရွေးချယ်ပါသည်။ မျှဝေခြင်းသည် မူကြမ်းကို Lift ထံ ပေးပို့ခြင်း မဟုတ်သကဲ့သို့ စိစစ်ပြီးသော အသိုင်းအဝိုင်းပို့စ်အဖြစ် ပြောင်းလဲခြင်းလည်း မဟုတ်ပါ။","Sharing is unavailable. You can copy or download your draft instead.":"မျှဝေ၍ မရပါ။ အစားထိုးအနေဖြင့် သင့်မူကြမ်းကို ကူးယူနိုင်ပါသည် သို့မဟုတ် ဒေါင်းလုဒ်လုပ်နိုင်ပါသည်။","Draft copied. You choose where to paste it.":"မူကြမ်းကို ကူးယူပြီးပါပြီ။ မည်သည့်နေရာတွင် ထည့်မည်ကို သင်ရွေးချယ်ပါသည်။","Copying is unavailable. You can download your draft instead.":"ကူးယူ၍ မရပါ။ အစားထိုးအနေဖြင့် သင့်မူကြမ်းကို ဒေါင်းလုဒ်လုပ်နိုင်ပါသည်။","Your draft was cleared from this page.":"သင့်မူကြမ်းကို ဤစာမျက်နှာမှ ရှင်းလင်းပြီးပါပြီ။","Reviewed community information":"စိစစ်ပြီးသော အသိုင်းအဝိုင်းအချက်အလက်များ","There are no reviewed community posts yet. Personal drafts are never added automatically.":"စိစစ်ပြီးသော အသိုင်းအဝိုင်းပို့စ်များ မရှိသေးပါ။ ကိုယ်ပိုင်မူကြမ်းများကို အလိုအလျောက် ထည့်သွင်းခြင်း လုံးဝမရှိပါ။","Before publication, a person must check the wording, remove identifying details and check sources. Legal and health information also needs a qualified reviewer. Experiences must be labelled as experiences.":"မထုတ်ဝေမီ လူတစ်ဦးက အသုံးအနှုန်းများကို စိစစ်ခြင်း၊ မည်သူဖြစ်ကြောင်း ဖော်ထုတ်နိုင်သော အချက်များကို ဖယ်ရှားခြင်းနှင့် ရင်းမြစ်များကို စစ်ဆေးခြင်း ပြုလုပ်ရပါမည်။ ဥပဒေနှင့် ကျန်းမာရေးအချက်အလက်များအတွက် သက်ဆိုင်ရာအရည်အချင်းရှိသော စိစစ်သူလည်း လိုအပ်ပါသည်။ အတွေ့အကြုံများကို အတွေ့အကြုံဖြစ်ကြောင်း တပ်ဖော်ပြရပါမည်။","Read the source":"ရင်းမြစ်ကို ဖတ်ပါ","Reviewed on":"စိစစ်ခဲ့သည့်ရက်","Review due":"ပြန်လည်စိစစ်ရမည့်ရက်","Review is overdue. Check the original source before relying on this post.":"ပြန်လည်စိစစ်ရမည့်ရက် ကျော်လွန်နေပါသည်။ ဤပို့စ်ကို မမှီခိုမီ မူရင်းရင်းမြစ်ကို စစ်ဆေးပါ။","Personal experience — may not apply to you":"ကိုယ်ပိုင်အတွေ့အကြုံ — သင့်အခြေအနေနှင့် ကိုက်ညီချင်မှ ကိုက်ညီပါမည်","Source-backed information":"ရင်းမြစ်အထောက်အထားရှိသော အချက်အလက်","This page is not monitored and cannot provide urgent help. Use a support service directly when you need assistance.":"ဤစာမျက်နှာကို စောင့်ကြည့်နေသူ မရှိသဖြင့် အရေးပေါ်အကူအညီ မပေးနိုင်ပါ။ အကူအညီလိုအပ်သည့်အခါ အကူအညီပေးသော ဝန်ဆောင်မှုကို တိုက်ရိုက် အသုံးပြုပါ။","Find support information":"အကူအညီဆိုင်ရာ အချက်အလက်ကို ရှာပါ","Back to my draft":"ကျွန်ုပ်၏မူကြမ်းသို့ ပြန်သွားပါ"});
/* community-copy:end */
function communityLabel(key){return LiftI18n.locale==='my'?communityMyanmar[key]:communityCopy[key];}
let communityDraft=LiftCommunity.normalize(),communityPreview=false,communityBusy=false;
function communityExport(){return LiftCommunity.exportText(communityDraft,communityLabel);}
function communityBoard(){const posts=window.LiftCommunityPosts||[];return `<section class="content-card"><h2>${communityLabel('board')}</h2>${posts.length?posts.map(p=>`<article class="community-post"><p class="community-badge">${communityLabel(p.kind==='experience'?'experienceLabel':'answerLabel')}</p><h3 data-user-content>${escapeText(p.title[LiftI18n.locale==='my'?'my':'en'])}</h3><p class="community-body" data-user-content>${escapeText(p.body[LiftI18n.locale==='my'?'my':'en'])}</p><p class="community-post-meta"><span>${icon('check')}${communityLabel('reviewed')}: ${escapeText(p.reviewedAt)}</span><span>${icon('steps')}${communityLabel('due')}: ${escapeText(p.reviewDue)}</span></p>${LiftCommunity.overdue(p.reviewDue)?`<p role="note">${communityLabel('stale')}</p>`:''}<div class="community-post-sources">${p.sources.map(url=>`<a href="${escapeText(url)}" target="_blank" rel="noopener noreferrer">${icon('book')}${communityLabel('source')}</a>`).join(' ')}</div></article>`).join(''):`<p>${communityLabel('noPosts')}</p>`}<details><summary>${communityLabel('reviewExplain')}</summary><p>${communityLabel('notEmergency')}</p></details></section>`;}
function communityPromptChoices(){if(typeof everydayLabel!=='function')return '';return `<details class="community-prompt-picker"><summary>${everydayLabel('title')}</summary>${['housing','transport','phone','food'].map((topic,i)=>`<details><summary>${icon(['home','bus','phone','basket'][i])}${everydayLabel(topic)}</summary><div class="community-prompt-list">${[1,2,3].map(n=>{const key=topic+n,label=everydayLabel(key),chosen=communityDraft.text.split('\n').some(line=>line.trim()===label);return `<button type="button" class="secondary" data-community-prompt="${key}" ${chosen?'disabled':''}>${escapeText(label)}</button>`;}).join('')}</div></details>`).join('')}</details>`;}
function communityPage(){const c=communityLabel;return heading('Your next step, together',c('title'),'')+`<p class="community-status" role="note">${icon('shield')}<span data-community-notice>${c('status')}</span></p><section class="content-card community-compose">${communityPreview?`<h2 tabindex="-1">${c('previewTitle')}</h2><pre class="export-preview community-body" data-user-content>${escapeText(communityExport())}</pre><p>${c('shareHelp')}</p><div class="community-actions"><button type="button" class="primary" data-community-action="share">${c('share')}</button><button type="button" class="secondary" data-community-action="copy">${c('copy')}</button><button type="button" class="secondary" data-community-action="download">${c('download')}</button><button type="button" class="text-button" data-community-action="edit">${c('edit')}</button></div>`:`${communityPromptChoices()}<form id="community-form" method="dialog"><label for="community-kind">${c('kind')}</label><select id="community-kind" data-community-field="kind">${['question','experience'].map(k=>`<option value="${k}" ${communityDraft.kind===k?'selected':''}>${c(k)}</option>`).join('')}</select><label for="community-topic">${c('topic')}</label><select id="community-topic" data-community-field="topic">${LiftCommunity.topics.map(k=>`<option value="${k}" ${communityDraft.topic===k?'selected':''}>${c(k)}</option>`).join('')}</select>${typeof communityChoiceFields==='function'?communityChoiceFields():''}<label for="community-text">${c('prompt')}</label><textarea id="community-text" data-community-field="text" maxlength="1200" rows="5" placeholder="${escapeText(c('placeholder'))}" aria-describedby="community-safety community-limit" data-user-content>${escapeText(communityDraft.text)}</textarea><p id="community-limit" class="community-count" aria-live="off">${communityDraft.text.length} / 1200</p><p id="community-safety">${c('safety')}</p><button type="submit" class="primary">${c('preview')}</button></form>`}<button type="button" class="text-button" data-community-action="clear">${c('clear')}</button><p class="community-privacy">${c('privacy')}</p><p id="community-feedback" role="status" aria-live="polite"></p></section>${communityBoard()}<a class="secondary" href="#resources" data-resource-topic="support">${c('help')}</a>`;}
function communityFeedback(key){const el=document.getElementById('community-feedback');if(el)el.textContent=communityLabel(key);}
document.addEventListener('input',event=>{const key=event.target.dataset.communityField;if(!key)return;communityDraft=LiftCommunity.normalize({...communityDraft,[key]:event.target.value});if(key==='text'){const el=document.getElementById('community-limit');if(el)el.textContent=communityDraft.text.length+' / 1200';}});
document.addEventListener('change',event=>{const key=event.target.dataset.communityField;if(key)communityDraft=LiftCommunity.normalize({...communityDraft,[key]:event.target.value});});
document.addEventListener('submit',event=>{if(event.target.id!=='community-form')return;event.preventDefault();if(!LiftCommunity.valid(communityDraft)){communityFeedback('empty');document.getElementById('community-text')?.focus();return;}communityPreview=true;route();const title=document.querySelector('.community-compose h2');title?.focus();title?.scrollIntoView({block:'start'});});
document.addEventListener('click',async event=>{
 const promptControl=event.target.closest('[data-community-prompt]');
 if(promptControl){const key=promptControl.dataset.communityPrompt;if(!/^(housing|transport|phone|food)[123]$/.test(key))return;const result=LiftCommunity.appendPrompt(communityDraft,everydayLabel(key));if(result.status==='full'){communityFeedback('tooLong');return;}if(result.status==='added'){communityDraft=result.draft;communityPreview=false;route();document.getElementById('community-text')?.focus();}return;}
 const control=event.target.closest('[data-community-action]');
 if(event.target.closest('[data-action="confirm-clear"]')){communityDraft=LiftCommunity.normalize();communityPreview=false;return;}
 if(!control)return;const action=control.dataset.communityAction;
 if(action==='clear'){communityDraft=LiftCommunity.normalize();communityPreview=false;route();communityFeedback('cleared');return;}
 if(action==='edit'){communityPreview=false;route();document.getElementById('community-text')?.focus();return;}
 if(!communityPreview||!LiftCommunity.valid(communityDraft)||communityBusy)return;
 const text=communityExport(),feedback=document.getElementById('community-feedback'),locale=LiftI18n.locale;
 function report(key){if(feedback?.isConnected&&LiftI18n.locale===locale)feedback.textContent=communityLabel(key);}
 if(action==='download'){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='lift-community-draft.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 communityBusy=true;control.disabled=true;
 try{if(action==='share'){if(!navigator.share){report('fallback');return;}await navigator.share({title:communityLabel('previewTitle'),text});}else if(action==='copy'){await navigator.clipboard.writeText(text);report('copied');}}catch(error){if(error.name!=='AbortError')report(action==='share'?'fallback':'copyFailed');}finally{communityBusy=false;if(control.isConnected)control.disabled=false;}
});
